(function(){var q=document.getElementById('q'),chips=document.querySelectorAll('.chip'),cards=document.querySelectorAll('[data-tool]'),cat='all';
function f(){var s=(q&&q.value||'').toLowerCase();var n=0;cards.forEach(function(c){var ok=(cat==='all'||c.dataset.cat===cat)&&c.dataset.text.indexOf(s)>-1;c.style.display=ok?'':'none';if(ok)n++});var e=document.querySelector('.empty');if(e)e.hidden=n>0;}
if(q){q.addEventListener('input',f);var u=new URLSearchParams(location.search).get('q');if(u){q.value=u;f()}}chips.forEach(function(b){b.addEventListener('click',function(){chips.forEach(function(x){x.classList.remove('on')});b.classList.add('on');cat=b.dataset.cat;f()})});
document.querySelectorAll('form.subscribe').forEach(function(fm){fm.addEventListener('submit',function(e){e.preventDefault();var m=fm.querySelector('.msg'),em=fm.querySelector('input[type=email],input:not([type])').value;var magnet=fm.getAttribute('data-magnet')||(fm.querySelector('[name=magnet]')||{}).value||'';m.textContent='Subscribing…';
fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:em,magnet:magnet})}).then(function(r){return r.json().then(function(j){m.textContent=j.message||(r.ok?'Thanks! You are subscribed.':'Something went wrong.');if(j.ok){var pdf=j.pdf||(magnet==='leaking-jobs'||magnet==='website-leaking-jobs'?'/downloads/website-leaking-jobs-checklist.pdf':'/downloads/ai-receptionist-checklist.pdf');m.innerHTML+=' <a href="'+pdf+'" target="_blank" style="font-weight:700;text-decoration:underline">Download the checklist (PDF)</a>'}})}).catch(function(){m.textContent='Signup is not live yet — check back soon.'})})});
/* leaking-jobs self-audit score */
var quiz=document.getElementById('leak-quiz');
if(quiz){var out=document.getElementById('leak-score');function score(){var boxes=quiz.querySelectorAll('input[type=checkbox]');var total=boxes.length,bad=0;boxes.forEach(function(b){if(!b.checked)bad++});if(!out)return;var tip=bad<=3?'Solid — keep an eye on follow-up speed.':bad<=8?'Fix phone and follow-up this week before you buy more ads.':'Leaky bucket — fix tap-to-call, offer, and missed-call reply first.';out.textContent='Unchecked: '+bad+' of '+total+'. '+tip;}quiz.addEventListener('change',score);score();}
})();
(function(){var n=Date.now();document.querySelectorAll('[data-promo-end]').forEach(function(e){var t=Date.parse(e.getAttribute('data-promo-end'));if(t&&n>t)e.remove()})})();
